},
"confidence": {
"type": "integer",
"minimum": 0,
"maximum": 100,
"description": "How sure you are, 0 to 100."
},
"risk": {
"type": "string",
"enum": ["LOW", "MEDIUM", "HIGH"],
"description": "How risky acting on this decision is right now."
},
"rationale": {
"type": "string",
"minLength": 1,
"maxLength": 500,
"description": "One or two sentences citing the numbers used."
}
}
}

