parameters.jsCode:
// What the AI sees: the market and your position, and no ids.
// Send Decision copies the ids Candleweb needs straight from Get the candles.
const data = $('Get the candles').item.json;

const withoutId = (block) => {
  if (!block) return null;
  const { position_id, ...rest } = block;
  return rest;
};

return {
  json: {
    sessionId: $json.sessionId,
    market: data.pair,
    timeframe: data.timeframe,
    stale: data.is_stale,
    position: withoutId(data.position),
    risk_preview: data.risk_preview,
    last_exit: withoutId(data.last_exit),
    candles: (data.candles || []).map((c) => ({
      time: c.open_time,
      open: c.open,
      high: c.high,
      low: c.low,
      close: c.close,
      volume: c.volume,
      closed: c.is_closed,
      indicators: c.indicators,
    })),
  },
};
